CREATE OR REPLACE FUNCTION public.revoke_pdv_access(target uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(742020); IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') OR target=auth.uid() THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF public.has_role(target,'admin') OR EXISTS(SELECT 1 FROM auth.users WHERE id=target AND lower(email)='ultraconnectsaborebrasa@gmail.com') THEN RAISE EXCEPTION 'Contas administradoras são protegidas'; END IF; DELETE FROM public.user_roles WHERE user_id=target AND role='operator'; END $$;
CREATE OR REPLACE FUNCTION public.set_pdv_role(target uuid,new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(742020); IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') OR target=auth.uid() THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF public.has_role(target,'admin') OR EXISTS(SELECT 1 FROM auth.users WHERE id=target AND lower(email)='ultraconnectsaborebrasa@gmail.com') THEN RAISE EXCEPTION 'Contas administradoras são protegidas'; END IF; IF new_role IS NULL THEN RAISE EXCEPTION 'Escolha um acesso válido'; END IF; DELETE FROM public.user_roles WHERE user_id=target; INSERT INTO public.user_roles(user_id,role) VALUES(target,new_role); END $$;
REVOKE ALL ON FUNCTION public.revoke_pdv_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.revoke_pdv_access(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.set_pdv_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_pdv_role(uuid,public.app_role) TO authenticated;